/**
 * Tab and app icons for the Workers that have no static assets (auth, profile). The sets are
 * generated by AlUmmahNow packages/app-icons (`--format ts`) into *.generated.ts next to this file.
 */
export type IconSet = Record<string, { type: string; body: string }>;

/** Fixed names, so not immutable: a day fresh, then a week stale-while-revalidate. */
export const ICON_CACHE_CONTROL = 'public, max-age=86400, stale-while-revalidate=604800';

/** A handler answering GET/HEAD for the set's paths; undefined for anything else. */
export function iconServer(set: IconSet): (pathname: string, method?: string) => Response | undefined {
	const bodies = new Map(Object.entries(set).map(([path, f]) => [path, { type: f.type, body: Uint8Array.from(atob(f.body), (ch) => ch.charCodeAt(0)) }]));
	return (pathname, method = 'GET') => {
		const f = bodies.get(pathname);
		if (!f || (method !== 'GET' && method !== 'HEAD')) return undefined;
		return new Response(method === 'HEAD' ? null : f.body, {
			headers: { 'Content-Type': f.type, 'Cache-Control': ICON_CACHE_CONTROL, 'X-Content-Type-Options': 'nosniff' },
		});
	};
}

/**
 * The SVG tab icon for an environment. Stage and production share a build, so this is chosen per
 * request: production plain, stage with a pink corner dot, QA and dev with a violet one.
 */
export function faviconSvgPath(environment: string | undefined): string {
	switch (environment) {
		case 'production':
			return '/favicon.svg';
		case 'stage':
		case 'staging':
			return '/favicon-stage.svg';
		default:
			return '/favicon-qa.svg';
	}
}

/** Environment from a host name (*.qa.alummahnow.net, *.stage.alummahnow.net), for apps without an env var. */
export function environmentOfHost(host: string): string {
	if (/(^|\.)qa\./.test(host)) return 'qa';
	if (/(^|\.)stage\./.test(host)) return 'stage';
	if (host === 'localhost' || host === '127.0.0.1' || host.endsWith('.workers.dev')) return 'development';
	return 'production';
}

/** <link> tags for a server-rendered page. */
export function iconLinks(environment: string | undefined, opts: { manifest?: boolean; themeColor?: string } = {}): string {
	return [
		'<link rel="icon" href="/favicon.ico" sizes="32x32">',
		`<link rel="icon" type="image/svg+xml" href="${faviconSvgPath(environment)}">`,
		'<link rel="apple-touch-icon" href="/apple-touch-icon.png">',
		opts.manifest ? '<link rel="manifest" href="/site.webmanifest">' : '',
		opts.themeColor ? `<meta name="theme-color" content="${opts.themeColor}">` : '',
	].filter(Boolean).join('\n    ');
}
